Query:
match cxxMemberCallExpr(
  callee(cxxMethodDecl(hasName("item"))),
  hasArgument(0, cxxMemberCallExpr(
    callee(cxxMethodDecl(hasName("row"))),
    on(declRefExpr(to(varDecl(hasInitializer(
      expr(ignoringParenImpCasts(cxxMemberCallExpr(callee(cxxMethodDecl(hasName("currentIndex"))))))
    )))))
  ))
).bind("item_call")
